 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(r for r, row in enumerate(grid) if all(x == 2 for x in row))
    out = [[0] * w for _ in range(h)]
    out[wall] = grid[wall][:]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4:
                continue
            # The examples show Manhattan-distance diamonds, clipped by the wall.
            radius = min(abs(wall - r), r, h - 1 - r, c, w - 1 - c)
            for dr in range(-radius, radius + 1):
                rr = r + dr
                dc = radius - abs(dr)
                if 0 <= rr < h and rr != wall:
                    for cc in {c - dc, c + dc}:
                        if 0 <= cc < w:
                            out[rr][cc] = 4
    return out
